import json
P=lambda *x: [[a,b] for a,b in x]
S=[
("abre","lavadora","Esto es una lavadora. Parece una caja que da vueltas y ya, pero por dentro tiene un tambor con huecos, un motor, una bomba y hasta bloques de concreto. Vamos a armarla desde cero.",P((0.05,"impacto"),(0.3,"whoosh"),(0.55,"pop"),(0.8,"mecanismo"))),
("balde","un balde","Si metes tu ropa sucia en un balde con agua y jabón, ya tienes una lavadora. Pero la mugre no se suelta sola, la ropa se queda ahí flotando y sigue sucia.",P((0.1,"chapoteo"),(0.4,"burbujas"),(0.75,"fallo"))),
("frotar","hay que frotarla","Así que la frotas con las manos, contra una tabla. El roce despega la mugre y el jabón se la lleva. Así se lavó la ropa durante siglos.",P((0.15,"swish"),(0.35,"swish"),(0.55,"swish"),(0.85,"ding"))),
("cansa","te cansas","Pero frotar cansa. Una sola cobija te deja los brazos rendidos, y tienes ropa para toda la semana.",P((0.25,"tension"),(0.6,"fallo"),(0.85,"alarma"))),
("tambor","un tambor","Así que metes la ropa en un tambor acostado, lleno de huequitos, y lo pones a girar. La ropa sube, se cae, se golpea con el agua y se frota sola contra sí misma.",P((0.15,"clink"),(0.4,"mecanismo"),(0.65,"chapoteo"),(0.85,"chapoteo"))),
("resbala","la ropa resbala","Pero la ropa resbala. Se queda abajo, arrastrándose, y no se levanta ni se golpea.",P((0.3,"swish"),(0.7,"fallo"))),
("paletas","unas aletas","Así que le pones unas aletas por dentro del tambor. Al girar, agarran la ropa, la suben hasta arriba y la dejan caer. Esas son las paletas.",P((0.15,"click"),(0.45,"whoosh"),(0.7,"chapoteo"),(0.9,"ding"))),
("chorrea","se sale el agua","Pero el tambor está lleno de huecos, y el agua se sale por todos lados. Te inunda el piso.",P((0.2,"gota"),(0.45,"agua_flujo"),(0.8,"fallo"))),
("tina","una tina cerrada","Así que metes el tambor dentro de otra tina, sin huecos y bien cerrada. El agua pasa entre los dos, pero no se escapa. Esa es la cuba.",P((0.15,"impacto"),(0.45,"clink"),(0.8,"ding"))),
("girar","¿quién lo gira?","Pero ahora hay que girar el tambor. Si lo haces con una manivela, otra vez terminas con los brazos rendidos.",P((0.25,"mecanismo"),(0.65,"fallo"))),
("motor","un motor","Así que le pones un motor abajo, con una correa de goma que agarra una polea grande pegada al tambor. La polea grande hace que gire más despacio pero con más fuerza.",P((0.15,"motor"),(0.45,"mecanismo"),(0.75,"motor"),(0.9,"ding"))),
("llenar","¿cómo entra el agua?","Pero cada vez tienes que llenarla con baldes, y si echas de más, se desborda.",P((0.2,"chapoteo"),(0.55,"agua_flujo"),(0.85,"fallo"))),
("valvula","una llave eléctrica","Así que la conectas a la llave del agua con una manguera, y pones una llave eléctrica que se abre sola. Esa es la electroválvula.",P((0.15,"click"),(0.45,"agua_flujo"),(0.8,"ding"))),
("cuanta","¿cuándo para?","Pero la válvula no sabe cuándo parar. Abre y abre, y el agua sigue subiendo hasta salirse por la puerta.",P((0.25,"agua_flujo"),(0.55,"alarma"),(0.85,"fallo"))),
("presostato","un tubito con aire","Así que le pones un tubito que baja hasta el fondo de la tina. Cuando sube el agua, aprieta el aire de adentro, y ese aire empuja un interruptor que cierra la válvula. Ese es el presostato.",P((0.15,"burbujas"),(0.45,"tension"),(0.7,"click"),(0.9,"ding"))),
("fria","el agua fría","Pero el agua sale fría de la llave, y con agua fría la grasa no se suelta tan fácil.",P((0.3,"misterio"),(0.7,"fallo"))),
("resistencia","un alambre caliente","Así que le metes abajo un alambre en espiral que se pone caliente con la electricidad, como el de una ducha eléctrica. Esa es la resistencia, y un sensor la apaga cuando el agua llega a la temperatura que escogiste.",P((0.15,"calor"),(0.45,"calor"),(0.7,"click"),(0.9,"ding"))),
("jabon","¿dónde va el jabón?","Pero si echas el jabón directo sobre la ropa, se queda pegado en una bola y deja manchas blancas.",P((0.25,"pop"),(0.65,"fallo"))),
("cajetin","un cajoncito","Así que le pones un cajoncito arriba. El agua que entra pasa primero por ahí, disuelve el jabón y lo lleva a la tina ya mezclado. Ese es el dispensador.",P((0.15,"clink"),(0.45,"agua_flujo"),(0.7,"burbujas"),(0.9,"ding"))),
("sucia","agua sucia","Pero cuando terminas de lavar, la tina queda llena de agua gris, con jabón y mugre. Y no tiene por dónde salir.",P((0.25,"chapoteo"),(0.6,"misterio"),(0.85,"fallo"))),
("bomba","una bomba","Así que le pones una bomba pequeña abajo, que chupa el agua sucia y la manda por una manguera al desagüe. Esa es la bomba de desagüe.",P((0.15,"motor"),(0.45,"agua_flujo"),(0.8,"ding"))),
("moneda","una moneda","Pero en los bolsillos siempre se queda algo. Una moneda, un botón, un gancho. Se van con el agua, entran en la bomba y la traban.",P((0.2,"clink"),(0.45,"clink"),(0.75,"impacto"),(0.9,"fallo"))),
("filtro","una tapita abajo","Así que pones un colador antes de la bomba, con una tapita en el frente de la lavadora para abrirlo y sacar lo que se atasca. Ese es el filtro, y casi nadie sabe que existe.",P((0.15,"click"),(0.45,"clink"),(0.75,"pop"),(0.9,"ding"))),
("mojada","sale empapada","Pero la ropa sale chorreando. Pesa el doble, y en el tendedero tarda días en secarse.",P((0.25,"gota"),(0.5,"gota"),(0.8,"fallo"))),
("centrifuga","girar rapidísimo","Así que pones el tambor a girar rapidísimo, más de mil vueltas por minuto. La ropa se pega contra las paredes y el agua sale disparada por los huequitos. Eso es el centrifugado.",P((0.15,"motor"),(0.4,"whoosh"),(0.65,"agua_flujo"),(0.9,"ding"))),
("baila","la lavadora baila","Pero la ropa nunca queda pareja. Si un lado pesa más, el tambor se tambalea, y la lavadora salta y camina por el piso.",P((0.2,"impacto"),(0.45,"impacto"),(0.7,"impacto"),(0.9,"alarma"))),
("concreto","bloques de concreto","Así que le pegas a la tina unos bloques de concreto, pesadísimos. Con tanto peso, la ropa ya casi no la mueve. Esos son los contrapesos, y por eso una lavadora pesa tanto.",P((0.15,"impacto"),(0.45,"impacto"),(0.8,"ding"))),
("resortes","resortes","Pero si la tina está pegada a la carcasa, todo el temblor pasa al piso y suena como un terremoto.",P((0.3,"tension"),(0.7,"fallo"))),
("amortiguar","colgarla","Así que la cuelgas de unos resortes arriba y la apoyas en unos pistones abajo, que frenan el rebote. Son los amortiguadores, como los de una moto.",P((0.15,"tension"),(0.45,"mecanismo"),(0.8,"ding"))),
("puerta","abres la puerta","Pero si abres la puerta en pleno lavado, se te sale toda el agua, y si la abres girando, te puedes lastimar la mano.",P((0.25,"agua_flujo"),(0.55,"alarma"),(0.85,"fallo"))),
("seguro","un seguro","Así que le pones un seguro que traba la puerta mientras hay agua o el tambor gira. Por eso suena un clac al empezar, y por eso esperas un rato al final antes de abrir.",P((0.15,"click"),(0.45,"impacto"),(0.75,"tic"),(0.9,"ding"))),
("goma","el borde se moja","Pero entre la puerta y la tina queda una rendija, y por ahí gotea.",P((0.3,"gota"),(0.7,"fallo"))),
("fuelle","un fuelle de goma","Así que le pones un fuelle de goma, como un acordeón, que une la tina con la puerta y se dobla cuando la tina se mueve. Ahí se esconden muchas medias perdidas.",P((0.15,"swish"),(0.45,"pop"),(0.8,"ding"))),
("cerebro","¿quién manda?","Pero ahora tienes válvula, motor, resistencia, bomba y seguro. Si los prendes a mano, uno por uno, te pasas el día pegado a la lavadora.",P((0.2,"click"),(0.4,"click"),(0.6,"click"),(0.85,"fallo"))),
("programa","una perilla","Así que le pones una perilla con un pequeño cerebro. Tú escoges el programa, y él decide cuándo abrir el agua, cuánto girar, cuándo calentar y cuándo exprimir.",P((0.15,"click"),(0.45,"tic"),(0.75,"mecanismo"),(0.9,"ding"))),
("ciclo","el ciclo completo","Y así va: entra el agua por el jabón, calienta, el tambor da vueltas, la bomba saca el agua sucia, entra agua limpia para enjuagar, y al final centrifuga.",P((0.1,"agua_flujo"),(0.35,"calor"),(0.6,"mecanismo"),(0.85,"motor"))),
("suavizante","el suavizante","Y el suavizante tiene su propio cajoncito. El cerebro lo deja para el último enjuague, para que no se vaya con el agua sucia.",P((0.2,"clink"),(0.55,"agua_flujo"),(0.85,"ding"))),
("llena","no la llenes","Pero si la llenas hasta el tope, la ropa no tiene espacio para subir y caer. No se golpea, no se frota, y sale casi igual de sucia.",P((0.25,"tension"),(0.6,"fallo"),(0.85,"alarma"))),
("espacio","deja una mano","Así que deja libre más o menos una mano de espacio arriba del tambor, para que la ropa pueda dar sus vueltas.",P((0.3,"whoosh"),(0.75,"ding"))),
("repaso","repaso","Repasemos. Un tambor con huecos y aletas, una tina cerrada, un motor con correa, una válvula, un presostato, una resistencia, una bomba con filtro, contrapesos de concreto, resortes y un seguro en la puerta.",P((0.1,"pop"),(0.3,"pop"),(0.5,"pop"),(0.7,"pop"),(0.9,"pop"))),
("cierre","así funciona","Tu lavadora no tiene manos: hace que la ropa se frote sola, subiendo y cayendo, miles de veces. Así funciona.",P((0.3,"brillo"),(0.7,"impacto"))),
("pregunta","¿qué armamos?","Si te gustó, síguenos, y escribe en los comentarios qué objeto quieres que armemos pieza por pieza.",P((0.3,"click"),(0.6,"campana"))),
]
json.dump([dict(tipo=a,titulo=b,texto=c,sfx=d) for a,b,c,d in S],open('escenas.json','w'),ensure_ascii=False,indent=1)
print(len(S), sum(len(c.split()) for _,_,c,_ in S))
